def min_absolute_difference(nums: List[int], k: int) -> int:
    """Return the smallest distance from k to the OR of a non-empty subarray."""
    best = float("inf")
    ending_ors: set[int] = set()
    for value in nums:
        ending_ors = {value} | {previous | value for previous in ending_ors}
        for value_or in ending_ors:
            distance = abs(value_or - k)
            if distance < best:
                best = distance
                if best == 0:
                    return 0
    return int(best)
